/* ============ IMAGERY SOURCE ============
   The artifact sandbox permits images.unsplash.com (with no-referrer) but blocks
   picsum/randomuser/wikimedia. So every real photo comes from Unsplash; a drawn
   SVG sits underneath so a 404 degrades to an illustration, never a broken frame. */
const uns = (id, w, h) => `https://images.unsplash.com/photo-${id}?auto=format&fit=crop&w=${w}&h=${h}&q=70`;
const unsFace = (id) => `https://images.unsplash.com/photo-${id}?auto=format&fit=facearea&facepad=3&w=256&h=256&q=70`;
/* Real photos come from whichever host the sandbox allows. We try several independent
   hosts in sequence so a blocked host or a stale id can't leave an empty frame:
   faces  → randomuser.me portraits (real people) → Unsplash faces
   scenes → Unsplash category → picsum seeded photo
   …and a drawn tile always sits underneath as the final guarantee. */
const HOSTS_OK = typeof window !== "undefined";
const ruFace = (seed, female) => `https://randomuser.me/api/portraits/${female ? "women" : "men"}/${hash(seed) % 90}.jpg`;
const picsum = (seed, w, h) => `https://picsum.photos/seed/${encodeURIComponent(seed)}/${w}/${h}`;
